<script setup lang="ts">
import { computed, ref, watch, nextTick } from 'vue'
import BenefitsMatrix from './BenefitsMatrix.vue'
import BenefitsAnalytics from './BenefitsAnalytics.vue'
import { capabilityFor, modeLabels, evidenceObservation } from '../capabilities'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import { Search, Download, X, ArrowUpRight } from 'lucide-vue-next'
import * as XLSX from 'xlsx'
import PrototypeEditor from './PrototypeEditor.vue'
import { catalog, metadata, rules, categoryDefinitions, vouchers, voucherStates, sources as sourceRows, checkEligibility, transitionVoucher, refreshSource, storageNotice, type Entity } from '../prototype-store'
import { people, observations, regions, contingents, statusLabels, personFor, summarize, filterObservations, type Decision, type Person } from '../domain'
const props=defineProps<{pageKey:string}>(), router=useRouter()
const route=useRoute()
const from=ref('2026-10-01'),to=ref('2026-10-29'),region=ref(''),category=ref(''),filterBenefit=ref(0),status=ref(''),query=ref(''),gender=ref(''),registry=ref('')
const filters=computed(()=>({from:from.value,to:to.value,region:region.value,category:category.value,benefitId:filterBenefit.value,status:status.value,search:query.value,gender:gender.value,registry:registry.value}))
watch([() => route.query, () => props.pageKey], ([q]) => {
 if (props.pageKey==='usage' && (typeof q.person==='string'||typeof q.category==='string')) {
  query.value=typeof q.person==='string'?q.person:'';filterBenefit.value=Number(q.benefit)||0;status.value=typeof q.status==='string'?q.status:'';region.value=typeof q.region==='string'?q.region:'';category.value=typeof q.category==='string'?q.category:'';gender.value='';registry.value=''
  from.value=typeof q.from==='string'?q.from:'2026-08-01';to.value=typeof q.to==='string'?q.to:'2026-10-29'
 }
}, {immediate:true})
const rows=computed(()=>filterObservations(observations,filters.value)), totals=computed(()=>summarize(rows.value)),page=ref(1)
const paged=computed(()=>rows.value.slice((page.value-1)*15,page.value*15))
watch(filters,()=>page.value=1)
const selected=ref<typeof catalog[number]|null>(null),profile=ref<Person|null>(null),closeButton=ref<HTMLButtonElement|null>(null)
watch(()=>props.pageKey,()=>{page.value=1;selected.value=null;profile.value=null})
watch([selected,profile],async()=>{if(selected.value||profile.value){await nextTick();closeButton.value?.focus()}})
const num=(n:number)=>n.toLocaleString('uz-UZ'),money=(n:number)=>num(n)+' so‘m',benefit=(id:number)=>catalog.find(b=>b.id===id)!
const typeOf=(b:typeof catalog[number])=>b.details.match(/Тури: ([^.\n]+)/)?.[1]??'Boshqa'
const kinds=computed(()=>[...new Set(catalog.map(typeOf))]),search=ref(''),kind=ref(''),catalogPage=ref(1)
const catalogRows=computed(()=>catalog.filter(b=>(!kind.value||typeOf(b)===kind.value)&&`${b.id} ${b.name} ${b.details}`.toLowerCase().includes(search.value.toLowerCase())))
watch([search,kind],()=>catalogPage.value=1)
function reset(){from.value='2026-10-01';to.value='2026-10-29';region.value='';category.value='';filterBenefit.value=0;status.value='';query.value='';gender.value='';registry.value=''}
function drill(s='',r='',c='',b=0){status.value=s;region.value=r;category.value=c;filterBenefit.value=b;query.value='';router.push('/apps/social-benefits/usage')}
const statusKeys=Object.keys(statusLabels) as Decision[]
const regional=computed(()=>regions.map(name=>({name,...summarize(rows.value.filter(r=>personFor(r.personId).region===name))})).sort((a,b)=>b.people-a.people))
const topBenefits=computed(()=>catalog.map(b=>({...b,...summarize(rows.value.filter(r=>r.benefitId===b.id))})).filter(b=>b.people).sort((a,b)=>b.events-a.events).slice(0,8))
const categoryRows=computed(()=>contingents.map(name=>({name,...summarize(rows.value.filter(r=>personFor(r.personId).categories.includes(name))),ids:categoryDefinitions.find(c=>c.name===name)?.benefitIds??[]})))
const trend=computed(()=>[8,9,10].map(month=>({name:['Avgust','Sentyabr','Oktyabr'][month-8],...summarize(filterObservations(observations,{...filters.value,from:`2026-${String(month).padStart(2,'0')}-01`,to:`2026-${String(month).padStart(2,'0')}-31`}))})))
const pinfl=ref(people[0]!.pinfl),checkBenefit=ref(observations[0]!.benefitId),asOf=ref('2026-10-29'),checked=ref(false),checkError=ref('')
const checkPerson=computed(()=>people.find(p=>p.pinfl===pinfl.value)),result=computed(()=>checkEligibility(checkPerson.value,checkBenefit.value,asOf.value))
watch([pinfl,checkBenefit,asOf],()=>checked.value=false)
watch([() => route.query, () => props.pageKey], ([q]) => {
 if(props.pageKey==='eligibility' && typeof q.pinfl==='string') {
  pinfl.value=q.pinfl;checkBenefit.value=Number(q.benefit)||1;asOf.value=typeof q.asOf==='string'?q.asOf:'2026-10-29'
  nextTick(runCheck)
 }
}, {immediate:true})
function runCheck(){checkError.value=/^\d{14}$/.test(pinfl.value)?'':'JShShIR 14 ta raqamdan iborat bo‘lishi kerak.';checked.value=!checkError.value}
function sample(s:Decision){const r=observations.find(o=>o.status===s)!;pinfl.value=personFor(r.personId).pinfl;checkBenefit.value=r.benefitId;asOf.value='2026-10-29';nextTick(runCheck)}
const personRows=computed(()=>profile.value?observations.filter(r=>r.personId===profile.value!.id).map(evidenceObservation):[])
const detailRows=computed(()=>selected.value?rows.value.filter(r=>r.benefitId===selected.value!.id):[]),detailTotals=computed(()=>summarize(detailRows.value))
const columns=[{key:'name',title:'Shaxs'},{key:'pinfl',title:'JShShIR'},{key:'region',title:'Hudud'},{key:'category',title:'Kontingentlar'},{key:'benefit',title:'Imtiyoz'},{key:'date',title:'Sana'},{key:'status',title:'Holat'},{key:'amount',title:'Summa'},{key:'source',title:'Manba'}]
const chosen=ref(columns.map(c=>c.key)),reportName=ref('Hududlar bo‘yicha tahlil'),notice=ref('')
type SavedReport={name:string;columns:string[];filters:typeof filters.value}
const saved=ref<SavedReport[]>([])
try{const data=JSON.parse(localStorage.getItem('sb-reports-v1')??'[]');if(Array.isArray(data))saved.value=data.filter(r=>typeof r.name==='string'&&Array.isArray(r.columns)&&r.columns.every((k:string)=>columns.some(c=>c.key===k))&&r.filters&&typeof r.filters.from==='string'&&typeof r.filters.to==='string')}catch{}
function saveReport(){if(!reportName.value.trim()||!chosen.value.length){notice.value='Hisobot nomi va kamida bitta ustunni tanlang.';return}const entry={name:reportName.value.trim(),columns:[...chosen.value],filters:{...filters.value}};saved.value=[...saved.value.filter(r=>r.name!==entry.name),entry];try{localStorage.setItem('sb-reports-v1',JSON.stringify(saved.value));notice.value='Hisobot sozlamalari saqlandi.'}catch{notice.value='Brauzer xotirasiga saqlab bo‘lmadi.'}}
function loadReport(r:SavedReport){reportName.value=r.name;chosen.value=[...r.columns];from.value=r.filters.from;to.value=r.filters.to;region.value=r.filters.region;category.value=r.filters.category;filterBenefit.value=r.filters.benefitId;status.value=r.filters.status;query.value=r.filters.search;gender.value=r.filters.gender;registry.value=r.filters.registry;notice.value='Saqlangan filtr va ustunlar ochildi.'}
function moveColumn(key:string,d:number){const i=chosen.value.indexOf(key),j=i+d;if(i<0||j<0||j>=chosen.value.length)return;[chosen.value[i],chosen.value[j]]=[chosen.value[j]!,chosen.value[i]!]}
function excel(data:Record<string,unknown>[],name:string){const book=XLSX.utils.book_new();XLSX.utils.book_append_sheet(book,XLSX.utils.json_to_sheet(data),'Natijalar');XLSX.utils.book_append_sheet(book,XLSX.utils.json_to_sheet([{Izoh:'NAMUNAVIY MA’LUMOTLAR — frontend prototip',...filters.value}]),'Filtrlar');XLSX.writeFile(book,name+'.xlsx')}
function exportRows(){excel(rows.value.map(r=>{const p=personFor(r.personId);const v:Record<string,unknown>={name:p.name,pinfl:p.pinfl,region:p.region,category:p.categories.join('; '),benefit:benefit(r.benefitId).name,date:r.date,status:statusLabels[r.status],amount:r.amount,source:r.source};return Object.fromEntries(chosen.value.map(k=>[columns.find(c=>c.key===k)!.title,v[k]]))}),'Ijtimoiy_imtiyozlar_namuna')}
function exportCatalog(){excel(catalogRows.value.map(b=>({'Raqam':String(b.id).padStart(3,'0'),'Nomi':b.name,'Turi':typeOf(b),'Manba tavsifi':b.details})),'Imtiyozlar_katalogi')}
const editor=ref<Entity|null>(null),editorId=ref(''),formNotice=ref('')
const formLabels:Record<Entity,string>={benefit:'Imtiyoz yaratish',rule:'Qoida yaratish',category:'Kontingent yaratish',person:'Shaxs qo‘shish',usage:'Foydalanish yozuvi',voucher:'Vaucher shakllantirish',source:'Manba qo‘shish'}
const pageForms:Record<string,Entity[]>={overview:['benefit','category','person','usage'],catalog:['benefit','rule'],contingents:['category','person'],eligibility:['person','rule'],people:['person'],usage:['usage','person'],vouchers:['voucher'],coverage:['source']}
function openEditor(entity:Entity,id=''){selected.value=null;profile.value=null;editor.value=entity;editorId.value=id}
function formSaved(message:string){formNotice.value=message;editor.value=null;page.value=1}
function changeVoucher(id:string){try{transitionVoucher(id);notice.value=`${id}: holat saqlandi.`}catch(e){notice.value=(e as Error).message}}
function syncSource(i:number){try{refreshSource(i);notice.value='Namunaviy manba yangilandi va saqlandi.'}catch(e){notice.value=(e as Error).message}}
const listedPeople=computed(()=>people.filter(p=>(!query.value||`${p.name} ${p.pinfl}`.toLowerCase().includes(query.value.toLowerCase()))&&(!region.value||p.region===region.value)&&(!category.value||p.categories.includes(category.value))))
</script>
<template>
<div class="sb-page overflow-y-auto">
<div class="sb-page-actions"><div class="sb-header-actions"><RouterLink v-if="pageKey==='overview'" to="/apps/social-benefits/risks" class="sb-primary">Risklar <ArrowUpRight :size="15" /></RouterLink><RouterLink v-if="pageKey==='overview'" to="/apps/social-benefits/matrix" class="sb-primary">Matritsa <ArrowUpRight :size="15" /></RouterLink><span class="sb-badge">Namuna</span></div></div>

<section v-if="['overview','usage','contingents','reports','people'].includes(pageKey)" class="sb-panel sb-filters"><div class="sb-toolbar"><label>Davr boshi<input v-model="from" type="date" /></label><label>Davr oxiri<input v-model="to" type="date" /></label><label>Hudud<select v-model="region" aria-label="Hudud filtri"><option value="">Barcha hududlar</option><option v-for="r in regions" :key="r">{{ r }}</option></select></label><label>Kontingent<select v-model="category" aria-label="Kontingent filtri"><option value="">Barcha kontingentlar</option><option v-for="c in contingents" :key="c">{{ c }}</option></select></label><button @click="reset">Tozalash</button></div><p v-if="from>to" class="sb-error" role="alert">Davr oxiri boshlanish sanasidan oldin bo‘lishi mumkin emas.</p></section>
<section v-if="pageForms[pageKey]" class="sb-panel sb-create-bar"><div><button v-for="entity in pageForms[pageKey]" :key="entity" @click="openEditor(entity)">+ {{ formLabels[entity] }}</button></div></section>
<p v-if="formNotice||storageNotice.text" class="sb-info" role="status">{{ formNotice||storageNotice.text }}</p>
<template v-if="pageKey==='people'"><section class="sb-panel"><div class="sb-toolbar"><input v-model="query" aria-label="Shaxslar ro‘yxatidan qidirish" placeholder="F.I.Sh. yoki JShShIR" /></div><p>{{ listedPeople.length }} ta shaxs</p><div class="sb-table-wrap"><table><thead><tr><th>Shaxs / JShShIR</th><th>Hudud / manzil</th><th>Kontingentlar</th><th>Oila / reyestr</th><th>Amallar</th></tr></thead><tbody><tr v-for="p in listedPeople.slice((page-1)*15,page*15)" :key="p.id"><td><b>{{ p.name }}</b><p class="sb-code">{{ p.pinfl }}</p></td><td>{{ p.region }}<p>{{ p.district }} · {{ p.mahalla }}</p></td><td>{{ p.categories.join(', ') }}</td><td>{{ p.familyId }}<p>{{ p.registry?'Reyestrda':'Reyestrda emas' }}</p></td><td><button @click="profile=p">Karta</button><button @click="openEditor('person',p.id)">Tahrirlash</button></td></tr><tr v-if="!listedPeople.length"><td colspan="5">Shaxs topilmadi.</td></tr></tbody></table></div><div class="sb-pagination"><span>{{ page }} / {{ Math.max(1,Math.ceil(listedPeople.length/15)) }}</span><button :disabled="page===1" @click="page--">Oldingi</button><button :disabled="page*15>=listedPeople.length" @click="page++">Keyingi</button></div></section></template><BenefitsAnalytics v-if="pageKey==='risks'||pageKey==='coverage'" :mode="pageKey as 'risks'|'coverage'" />
<BenefitsMatrix v-if="pageKey==='matrix'" />

<template v-if="pageKey==='overview'">

<div class="sb-stats"><button @click="drill('',region,category)"><span>Qamrab olingan shaxslar</span><strong>{{ num(totals.people) }}</strong><small>{{ totals.families }} ta takrorlanmas oila</small></button><button class="metric-good" @click="drill('',region,category)"><span>Tasdiqlangan foydalanish</span><strong>{{ num(totals.events) }}</strong><small>{{ totals.benefits }} ta imtiyoz bo‘yicha</small></button><button :class="totals.unused>0?'metric-danger':'metric-good'" @click="drill('unused',region,category)"><span>Huquqi bor, foydalanmagan</span><strong>{{ num(totals.unused) }}</strong><small>Shaxs–imtiyoz baholashlari</small></button><button :class="totals.mismatch>0?'metric-danger':'metric-good'" @click="drill('mismatch',region,category)"><span>Mos kelmagan foydalanish</span><strong>{{ num(totals.mismatch) }}</strong><small>Tekshirilishi lozim bo‘lgan holatlar</small></button></div>
<div class="sb-two"><section class="sb-panel"><h2>Huquq va foydalanish holati</h2><p>Tanlangan davrdagi baholash yozuvlari</p><button v-for="s in statusKeys" :key="s" :class="['sb-distribution',s]" @click="drill(s,region,category)"><span>{{ statusLabels[s] }}</span><b>{{ num(totals[s]) }}</b><div class="sb-bar"><i :class="s" :style="{width:`${totals[s]/Math.max(rows.length,1)*100}%`}" /></div><small>{{ (totals[s]/Math.max(rows.length,1)*100).toFixed(1) }}%</small></button></section><section class="sb-panel"><h2>Oylik foydalanish dinamikasi</h2><p>Avgust–oktyabr · hudud va kontingent filtrlari saqlanadi</p><div class="sb-chart"><div v-for="t in trend" :key="t.name"><b>{{ t.events }}</b><div :style="{height:`${Math.max(4,t.events/Math.max(...trend.map(t=>t.events),1)*130)}px`}" /><span>{{ t.name }}</span></div></div><div class="sb-callout">Tanlangan davrda ma’lum summalar: <b>{{ money(totals.amount) }}</b><br />{{ totals.missingAmounts }} holatda summa noma’lum. Bu holatlar nol to‘lov emas.</div></section></div>
<section class="sb-panel"><h2>Hududlar bo‘yicha taqsimot</h2><div class="sb-table-wrap"><table><thead><tr><th>Hudud</th><th>Shaxslar</th><th>Oilalar</th><th>Foydalanishlar</th><th>Foydalanmagan</th><th>Aniqlanmagan</th><th>Ma’lum summa</th><th></th></tr></thead><tbody><tr v-for="r in regional" :key="r.name"><td>{{ r.name }}</td><td>{{ r.people }}</td><td>{{ r.families }}</td><td class="tone-good">{{ r.events }}</td><td :class="r.unused>0?'tone-bad':'tone-neutral'">{{ r.unused }}</td><td :class="r.unknown>0?'tone-warning':'tone-neutral'">{{ r.unknown }}</td><td>{{ money(r.amount) }}</td><td><button @click="drill('',r.name,category)">Tahlil <ArrowUpRight :size="13" /></button></td></tr></tbody></table></div></section>
<section class="sb-panel"><h2>Eng ko‘p foydalanilgan imtiyozlar</h2><div v-for="b in topBenefits" :key="b.id" class="sb-status"><span class="sb-code">{{ b.id }}</span><div><button class="sb-text" @click="selected=b">{{ b.name }}</button><p>{{ b.people }} shaxs · {{ b.events }} foydalanish · {{ money(b.amount) }}</p></div><button @click="drill('',region,category,b.id)">Ro‘yxat</button></div><p v-if="!rows.length">Tanlangan filtrlar bo‘yicha natija topilmadi.</p></section>
</template>
<template v-else-if="pageKey==='catalog'">
<section class="sb-panel"><div class="sb-toolbar"><label class="sb-search"><Search :size="17" /><input v-model="search" placeholder="Raqam, nom yoki huquqiy asos bo‘yicha qidirish" aria-label="Katalogdan qidirish" /></label><select v-model="kind" aria-label="Chora turi"><option value="">Barcha turlar</option><option v-for="k in kinds" :key="k">{{ k }}</option></select><button @click="exportCatalog"><Download :size="16" /> Excel</button></div><p>{{ catalogRows.length }} ta mustaqil chora · Davr {{ from }} — {{ to }} davri uchun</p><div class="sb-table-wrap"><table><thead><tr><th>Raqam</th><th>Imtiyoz / yordam chorasi</th><th>Turi</th><th>Tekshiruv imkoniyati</th><th>Qamrov</th><th></th></tr></thead><tbody><tr v-for="b in catalogRows.slice((catalogPage-1)*15,catalogPage*15)" :key="b.id"><td class="sb-code">{{ String(b.id).padStart(3,'0') }}</td><td class="sb-name">{{ b.name }}</td><td>{{ typeOf(b) }}</td><td><RouterLink :to="{path:'/apps/social-benefits/coverage',query:{benefit:b.id}}"><span :class="capabilityFor(b.id).eligibility==='auto'?'tone-good':'tone-warning'">Moslik: {{ modeLabels[capabilityFor(b.id).eligibility] }}</span><br /><span :class="capabilityFor(b.id).usage==='auto'?'tone-good':'tone-warning'">Foydalanish: {{ modeLabels[capabilityFor(b.id).usage] }}</span></RouterLink></td><td>{{ summarize(rows.filter(r=>r.benefitId===b.id)).people }} shaxs</td><td><button @click="selected=b">Batafsil</button><button @click="openEditor('benefit',String(b.id))">Tahrirlash</button></td></tr><tr v-if="!catalogRows.length"><td colspan="5">Imtiyoz topilmadi.</td></tr></tbody></table></div><div class="sb-pagination"><span>{{ catalogPage }} / {{ Math.max(1,Math.ceil(catalogRows.length/15)) }} sahifa</span><button :disabled="catalogPage===1" @click="catalogPage--">Oldingi</button><button :disabled="catalogPage*15>=catalogRows.length" @click="catalogPage++">Keyingi</button></div></section>
</template>
<template v-else-if="pageKey==='contingents'">
<section class="sb-panel"><h2>Kontingentlar kesimida imtiyozlar taqsimoti</h2><div class="sb-table-wrap"><table><thead><tr><th>Kontingent</th><th>Shaxslar</th><th>Bog‘langan choralar</th><th>Foydalanish</th><th>Foydalanmagan</th><th>Ma’lum summa</th><th></th></tr></thead><tbody><tr v-for="c in categoryRows" :key="c.name"><td>{{ c.name }}</td><td>{{ c.people }}</td><td>{{ c.ids.length }}</td><td class="tone-good">{{ c.events }}</td><td :class="c.unused>0?'tone-bad':'tone-neutral'">{{ c.unused }}</td><td>{{ money(c.amount) }}</td><td><button @click="drill('',region,c.name)">Shaxslar</button><button @click="openEditor('category',c.name)">Tahrirlash</button></td></tr></tbody></table></div></section><section class="sb-panel"><h2>Kontingentning imtiyozlar xaritasi</h2><div v-for="c in categoryRows.filter(c=>!category||c.name===category)" :key="c.name" class="sb-status"><div><b>{{ c.name }}</b><p>{{ c.people }} shaxs · {{ c.ids.length }} ta chora</p><div class="sb-chips"><button v-for="id in c.ids" :key="id" @click="selected=benefit(id)" :title="benefit(id).name">{{ String(id).padStart(3,'0') }}</button></div></div></div></section>
</template>
<template v-else-if="pageKey==='eligibility'">
<section class="sb-panel"><div class="sb-chips"><button @click="sample('used')">Mos shaxs namunasi</button><button @click="sample('mismatch')">Mos kelmagan namuna</button><button @click="sample('unknown')">Ma’lumoti yetishmagan namuna</button></div><form class="sb-form" @submit.prevent="runCheck"><label>JShShIR<input v-model="pinfl" inputmode="numeric" maxlength="14" required /></label><label>Imtiyoz<select v-model="checkBenefit"><option v-for="b in catalog" :key="b.id" :value="b.id">{{ b.id }} · {{ b.name }}</option></select></label><label>Tekshiruv sanasi<input v-model="asOf" type="date" required /></label><button class="sb-primary">Tekshirish</button></form><p class="sb-error" role="alert">{{ checkError }}</p></section>
<section v-if="checked" class="sb-panel"><div class="sb-panel-heading"><div><h2 :class="result.outcome==='eligible'?'tone-good':result.outcome==='ineligible'?'tone-bad':'tone-warning'">{{ result.outcome==='eligible'?'Imtiyoz shartlariga mos':result.outcome==='ineligible'?'Imtiyoz shartlariga mos emas':'Huquqi aniqlanmagan' }}</h2><p>{{ result.reason }}</p></div><span class="sb-tag">{{ rules.find(r=>r.benefitId===checkBenefit&&r.state==='Faol'&&r.start<=asOf&&r.end>=asOf)?.version||'Demo qoida v1' }}</span></div><div v-if="checkPerson" class="sb-callout"><b>{{ checkPerson.name }}</b><p>{{ checkPerson.pinfl }} · {{ checkPerson.age }} yosh · {{ checkPerson.region }} · {{ checkPerson.registry?'Reyestrda':'Reyestrda emas' }}</p><button @click="profile=checkPerson">Shaxs kartasini ochish</button></div><table><thead><tr><th>Mezon</th><th>Natija</th></tr></thead><tbody><tr v-for="c in result.criteria" :key="c.name"><td>{{ c.name }}</td><td>{{ c.result }}</td></tr></tbody></table><p>Tekshiruv sanasi: {{ asOf }} · Imtiyoz: {{ checkBenefit }} · Tarixiy yozuvlar: {{ result.history.length }}</p></section>
</template>
<template v-else-if="pageKey==='usage'||pageKey==='reports'">
<section v-if="pageKey==='reports'" class="sb-panel"><p>Ustunlar va filtrlar</p><div class="sb-report-columns"><div v-for="c in columns" :key="c.key"><label><input type="checkbox" :value="c.key" v-model="chosen" /> {{ c.title }}</label><button :disabled="chosen.indexOf(c.key)<=0" @click="moveColumn(c.key,-1)">↑</button><button :disabled="!chosen.includes(c.key)||chosen.indexOf(c.key)===chosen.length-1" @click="moveColumn(c.key,1)">↓</button><small v-if="chosen.includes(c.key)">{{ chosen.indexOf(c.key)+1 }}</small></div></div><div class="sb-toolbar"><input v-model="reportName" aria-label="Hisobot nomi" placeholder="Hisobot nomi" /><button @click="saveReport">Sozlamalarni saqlash</button></div><div class="sb-chips"><button v-for="r in saved" :key="r.name" @click="loadReport(r)">{{ r.name }}</button></div><p role="status">{{ notice }}</p></section>
<section class="sb-panel"><div class="sb-toolbar"><input v-model="query" placeholder="Shaxs yoki JShShIR" aria-label="Shaxsni qidirish" /><select v-model="status" aria-label="Holat"><option value="">Barcha holatlar</option><option v-for="s in statusKeys" :key="s" :value="s">{{ statusLabels[s] }}</option></select><select v-model="gender" aria-label="Jins"><option value="">Barcha jinslar</option><option>Ayol</option><option>Erkak</option></select><select v-model="registry" aria-label="Reyestr"><option value="">Reyestr: barchasi</option><option value="true">Reyestrda</option><option value="false">Reyestrda emas</option></select><button :disabled="!chosen.length||!rows.length||from>to" @click="exportRows"><Download :size="16" /> Excel</button></div><label class="sb-wide-select">Imtiyoz<select v-model="filterBenefit"><option :value="0">Barcha imtiyozlar</option><option v-for="b in catalog" :key="b.id" :value="b.id">{{ b.id }} · {{ b.name }}</option></select></label><p><b>{{ totals.people }}</b> shaxs · {{ totals.families }} oila · {{ rows.length }} baholash · {{ totals.events }} foydalanish · {{ money(totals.amount) }} · {{ totals.missingAmounts }} holatda summa yo‘q</p>
<div class="sb-table-wrap"><table><thead><tr><th v-for="key in chosen" :key="key">{{ columns.find(c=>c.key===key)?.title }}</th><th>Karta</th></tr></thead><tbody><tr v-for="r in paged" :key="r.id"><td v-for="key in chosen" :key="key"><template v-if="key==='name'">{{ personFor(r.personId).name }}</template><span v-else-if="key==='pinfl'" class="sb-code">{{ personFor(r.personId).pinfl }}</span><template v-else-if="key==='region'">{{ personFor(r.personId).region }}</template><template v-else-if="key==='category'">{{ personFor(r.personId).categories.join(', ') }}</template><button v-else-if="key==='benefit'" class="sb-text sb-name" @click="selected=benefit(r.benefitId)">{{ r.benefitId }} · {{ benefit(r.benefitId).name }}</button><template v-else-if="key==='date'">{{ r.date }}</template><span v-else-if="key==='status'" :class="['sb-tag',r.status]">{{ statusLabels[r.status] }}</span><template v-else-if="key==='amount'">{{ r.amount===null?'Ma’lumot yo‘q':money(r.amount) }}</template><template v-else-if="key==='source'">{{ r.source }} · demo</template></td><td><button @click="profile=personFor(r.personId)">Ochish</button><button @click="openEditor('usage',r.id)">Tahrirlash</button></td></tr><tr v-if="!rows.length"><td :colspan="chosen.length+1">Tanlangan filtrlar bo‘yicha yozuv topilmadi.</td></tr></tbody></table></div><div class="sb-pagination"><span>{{ page }} / {{ Math.max(1,Math.ceil(rows.length/15)) }} sahifa · {{ rows.length }} yozuv</span><button :disabled="page===1" @click="page--">Oldingi</button><button :disabled="page*15>=rows.length" @click="page++">Keyingi</button></div></section>
</template>
<template v-else-if="pageKey==='vouchers'">
<div class="sb-stats"><div v-for="s in voucherStates" :key="s"><span>{{ s }}</span><strong>{{ vouchers.filter(v=>v.state===s).length }}</strong></div></div><section class="sb-panel"><p role="status">{{ notice }}</p><div class="sb-table-wrap"><table><thead><tr><th>Vaucher / bola</th><th>Qonuniy vakil</th><th>Hudud</th><th>Holat / amal muddati</th><th>To‘lov</th><th>Amal</th></tr></thead><tbody><tr v-for="v in vouchers" :key="v.id"><td><b>{{ v.id }}</b><p>{{ v.child }}</p><small>{{ v.kindergarten }} · {{ v.plan }}</small><details><summary>Holatlar tarixi</summary><p v-for="(h,i) in v.history" :key="i">{{ h }}</p></details></td><td>{{ v.parent }}</td><td>{{ v.region }}</td><td><span :class="['sb-tag',v.state==='Faol'?'used':v.state==='Vaqtincha nofaol'?'unknown':'neutral']">{{ v.state }}</span><p>{{ v.start }} — {{ v.end }}</p></td><td>Manba tasdig‘i kutilmoqda</td><td><button :disabled="v.state==='Yakunlangan'" @click="changeVoucher(v.id)">{{ v.state==='Shakllangan'?'Faollashtirish':v.state==='Faol'?'Vaqtincha to‘xtatish':v.state==='Vaqtincha nofaol'?'Qayta faollashtirish':'Yakunlangan' }}</button><button @click="openEditor('voucher',v.id)">Tahrirlash</button></td></tr></tbody></table></div></section>
</template>
<details v-if="pageKey==='coverage'" class="sb-panel sb-sources"><summary>Manbalar sozlamalari <span>{{ sourceRows.length }}</span></summary><div class="sb-table-wrap"><table><thead><tr><th>Manba</th><th>Holati</th><th>Yangilanish</th><th>To‘liqlik</th><th></th></tr></thead><tbody><tr v-for="(s,i) in sourceRows" :key="s.name"><td>{{ s.name }}</td><td><span :class="['sb-tag',s.status==='Yangilangan'?'used':'unknown']">{{ s.status }}</span></td><td>{{ s.time }}</td><td :class="s.coverage<90?'tone-bad':s.coverage<98?'tone-warning':'tone-good'">{{ s.coverage }}%</td><td><button @click="syncSource(i)">Yangilash</button><button @click="openEditor('source',s.name)">Tahrirlash</button></td></tr></tbody></table></div><p role="status">{{ notice }}</p></details>
<section v-if="pageKey==='eligibility'||pageKey==='catalog'" class="sb-panel"><h2>Muvofiqlik qoidalari</h2><table><thead><tr><th>Imtiyoz</th><th>Versiya / holat</th><th>Yosh / shartlar</th><th>Amal sanalari</th><th></th></tr></thead><tbody><tr v-for="r in rules" :key="r.benefitId+':'+r.version"><td>{{ r.benefitId }} · {{ benefit(r.benefitId).name }}</td><td>{{ r.version }} · {{ r.state }}</td><td>{{ r.minAge }}–{{ r.maxAge }} yosh<p>{{ r.categories.join(', ')||'Barcha kontingentlar' }}</p></td><td>{{ r.start }} — {{ r.end }}</td><td><button @click="openEditor('rule',r.benefitId+':'+r.version)">Tahrirlash</button></td></tr><tr v-if="!rules.length"><td colspan="5">Maxsus qoida hali kiritilmagan. Demo faktlardan foydalaniladi.</td></tr></tbody></table></section>
<PrototypeEditor v-if="editor" :key="editor+editorId" :entity="editor" :edit-id="editorId" @close="editor=null" @saved="formSaved" />
<div v-if="selected||profile" class="sb-overlay" @click.self="selected=null;profile=null" @keydown.esc="selected=null;profile=null"><section class="sb-dialog" role="dialog" aria-modal="true" aria-labelledby="detail-title"><div class="sb-panel-heading"><span class="sb-code">{{ profile?'Shaxs kartasi · NAMUNA':'Imtiyoz kartasi · '+selected?.id }}</span><button ref="closeButton" @click="selected=null;profile=null" aria-label="Yopish"><X :size="18" /></button></div><template v-if="profile"><h2 id="detail-title">{{ profile.name }}</h2><button @click="openEditor('person',profile.id)">Shaxsni tahrirlash</button><div class="sb-profile-grid"><div v-for="(value,key) in {JShShIR:profile.pinfl,Yosh:profile.age,Jins:profile.gender,Hudud:profile.region,Tuman:profile.district,Mahalla:profile.mahalla,Oila:profile.familyId,Reyestr:profile.registry?'Kiritilgan':'Kiritilmagan'}" :key="key"><small>{{ key }}</small><b>{{ value }}</b></div></div><p>{{ profile.categories.join(' · ') }}</p><h3>Imtiyozlar va foydalanish tarixi</h3><div v-for="r in personRows" :key="r.id" class="sb-status"><div><b>{{ r.benefitId }} · {{ benefit(r.benefitId).name }}</b><p>{{ r.date }} · {{ statusLabels[r.status] }}</p><p>{{ r.source }} · {{ r.amount===null?'Summa mavjud emas':money(r.amount) }}</p></div></div></template><template v-else-if="selected"><h2 id="detail-title">{{ selected.name }}</h2><button @click="openEditor('benefit',String(selected.id))">Imtiyozni tahrirlash</button><div v-if="metadata[selected.id]" class="sb-callout"><b>{{ metadata[selected.id]?.organization }}</b><p>Manba: {{ metadata[selected.id]?.source }} · {{ metadata[selected.id]?.start }} — {{ metadata[selected.id]?.end }}</p><p>{{ metadata[selected.id]?.categories.join(' · ') }}</p></div><div class="sb-stats sb-detail-stats"><div><span>Shaxslar</span><strong>{{ detailTotals.people }}</strong></div><div><span>Foydalanish</span><strong>{{ detailTotals.events }}</strong></div></div><h3>Shartlar va huquqiy asos · hujjatdagi ma’lumot</h3><pre>{{ selected.details }}</pre><h3>Kontingentlar · demo taqsimot</h3><p>{{ [...new Set(detailRows.flatMap(r=>personFor(r.personId).categories))].join(' · ')||'Tanlangan davrda ma’lumot yo‘q' }}</p><div class="sb-callout">{{ from }} — {{ to }}: {{ money(detailTotals.amount) }} · {{ detailTotals.missingAmounts }} holatda summa noma’lum.</div><button class="sb-primary" @click="drill('',region,category,selected.id);selected=null">Shaxslar ro‘yxatiga o‘tish</button></template></section></div>
</div>
</template>
<style scoped src="./social-benefits.css"></style>
<style src="./benefits-colors.css"></style>
